import{z as l,x as s,o as B,c as d,q as i,j as o,D as a,d as e,s as n,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"IPO 与发行时机","description":"","frontmatter":{"title":"IPO 与发行时机","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-ipo-timing.md","filePath":"econ/cf-ipo-timing.md","lastUpdated":1791413859000}'),p={name:"econ/cf-ipo-timing.md"};function C(c,E,h,m,u,F){const t=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=i('<h1 id="ipo-与发行时机" tabindex="-1">IPO 与发行时机 <a class="header-anchor" href="#ipo-与发行时机" aria-label="Permalink to &quot;IPO 与发行时机&quot;">​</a></h1><div class="epigraph"><p>发行时机是公司金融里少数「事后看得清、事前全是雾」的决策：窗口是市场给的，进不进、进多少，是企业自己排的队。</p><footer>—— 据 Ritter 1991 与 Loughran–Ritter 2002 整理</footer></div><p><a href="/econ/cf-dividends-buybacks">上一课</a>把分钱的管道钉住：持久现金用股利买承诺，临时现金用回购保灵活。本课转到收钱的一端——把股份卖给公众。主干课的<a href="/econ/ipo-underpricing-theory">IPO 抑价作为理论</a>钉了定价侧：赢者诅咒、信号与信息瀑布解释发行价为什么低于首日价。缺口在时机侧：什么时候发、发多少、为什么热发行市场与发行后的长期弱势会同时出现。这是<a href="/econ/market-timing-theory">市场择时理论</a>在企业决策上的正面战场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个量必须分开。抑价是发行价与首日收盘价的差，是<strong>定价</strong>问题；时机是发行窗口的选择，是<strong>配置</strong>问题——发行便宜不等于发行时机好。经验事实有三条：IPO 在时间上扎堆（热市场）；发行公司集中在自身行业估值的高点发行；发行后三到五年相对收益系统性偏弱（Ritter 1991）。解释分两个方向：理性侧，公司对自身价值有私有信息，选需求最旺的窗口卖；行为侧，情绪高时投资者对增长故事的折现小，<a href="/econ/noise-trader-risk">噪声交易者风险 DSSW</a> 所描述的环境恰好打开了窗口。</p><p><span class="marginnote">把两个量翻译开：抑价像「开业打折」——发行价定得低于首日收盘价，钱留在了桌上；时机像「挑开业的日子」——选在客人最多、最肯花钱的窗口。打折打得狠不代表日子挑得好：两者同源（信息不对称），却发生在定价与配置两个不同界面。</span></p><h3 id="择时作为政策" tabindex="-1">择时作为政策 <a class="header-anchor" href="#择时作为政策" aria-label="Permalink to &quot;择时作为政策&quot;">​</a></h3><p>Baker–Wurgler 2002 把择时从「一次性机会主义」升格为政策：市值账面比高时发股、低时回购，外部融资加权平均的市值账面比对杠杆有持久解释力——择时留下的不是快进快出的头寸，而是资本结构的结构性疤痕。这与上一课的分配政策互为镜像：回购与股利用现金换回被低估的股份，发行是反过来在被高估时卖。</p><p><span class="marginnote">直觉类比：「疤痕」像在房价高点买的房——成交那一刻不觉得，之后每个月的房贷都记着那次择时。估值高时发的股让公司此后多年维持更低杠杆，估值低时的回购则相反。择时不是快进快出的头寸，是改写了资产负债表的长期形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检验择时要同时看量与质：发行量在估值窗口扎堆（量的证据）；发行公司的事后盈利与收益弱于配对样本（质的证据）。Loughran–Ritter 2002 补上行为侧的两块拼图：其一，管理层以发行前内部持股估值做锚，发行价翻倍仍觉得「没卖亏」，抑价的痛感被锚点吸收；其二，1990s 热窗口里发行的公司，IPO 后首年的分析师盈利预测相对实现的落差系统性为负——窗口里挤进来的恰是故事最经不起兑现的企业。两句合起来：热窗口既是企业主动择时的结果，也是市场筛选放行的结果。</p>',11)),(B(),o(A,null,{default:a(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SENT%5B%22%E6%83%85%E7%BB%AA%E4%B8%8E%E4%BC%B0%E5%80%BC%E7%AA%97%E5%8F%A3%E6%89%93%E5%BC%80%22%5D%20--%3E%20QUEUE%5B%22%E5%8F%91%E8%A1%8C%E6%8E%92%E9%98%9F%E4%B8%8E%E6%89%BF%E9%94%80%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20QUEUE%20--%3E%20ISSUE%5B%22%E5%8F%91%E8%A1%8C%EF%BC%9A%E6%8A%91%E4%BB%B7%E4%B8%8E%E5%8B%9F%E8%B5%84%E9%A2%9D%22%5D%0A%20%20ISSUE%20--%3E%20POST%5B%22%E5%8F%91%E8%A1%8C%E5%90%8E%E4%B8%89%E5%88%B0%E4%BA%94%E5%B9%B4%E7%9B%B8%E5%AF%B9%E5%BC%B1%E5%8A%BF%22%5D%0A%20%20POST%20--%3E%20ANCHOR%5B%22%E9%94%9A%E7%82%B9%E6%94%B9%E5%86%99%EF%BC%9A%E4%B8%8B%E4%B8%80%E8%BD%AE%E7%9A%84%E5%8F%82%E7%85%A7%22%5D%0A%20%20ANCHOR%20--%3E%20NEXT%7B%22%E4%B8%8B%E4%B8%80%E7%AA%97%E5%8F%A3%E4%BD%95%E6%97%B6%E5%BC%80%3F%22%7D%0A%20%20NEXT%20--%3E%20SENT%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=r("p",null,"为什么热窗口能存在：情绪高时发行企业与投资者之间的信息不对称被「故事折价小」放大，承销商的定价能力与排队拥堵也集中在窗口内，两边一起把发行量推成尖峰。为什么企业不全等窗口：现金需求、产品市场的竞争时机、以及窗口本身不可预测——等下一班车的成本同样是成本，择时最优不等于等待免费。为什么事后弱势与理性择时兼容：在高点发行意味着以高折现率资本化乐观预期，只要均值回归发生，弱势就是择时成功的对称面，不必假设发行方全员非理性。",-1)),(B(),o(A,null,{default:a(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E4%BC%81%E4%B8%9A%E9%9C%80%E8%A6%81%E7%8E%B0%E9%87%91%EF%BC%9A%E9%A1%B9%E7%9B%AE%E4%B8%8E%E7%AB%9E%E4%BA%89%E5%9C%A8%E7%AD%89%22%5D%20--%3E%20W%7B%22%E7%8E%B0%E5%9C%A8%E5%8F%91%EF%BC%8C%E8%BF%98%E6%98%AF%E7%AD%89%E7%AA%97%E5%8F%A3%3F%22%7D%0A%20%20W%20--%3E%7C%E7%8E%B0%E5%9C%A8%E5%8F%91%7C%20N%5B%22%E9%81%BF%E5%BC%80%E6%8B%A5%E6%8C%A4%EF%BC%8C%E6%8A%91%E4%BB%B7%E4%BD%8E%E4%B8%80%E4%BA%9B%22%5D%0A%20%20N%20--%3E%20R%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E9%94%99%E8%BF%87%E9%AB%98%E4%BC%B0%E5%80%BC%EF%BC%8C%E5%8D%96%E5%BE%97%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20W%20--%3E%7C%E7%AD%89%E7%AA%97%E5%8F%A3%7C%20L%5B%22%E4%BC%B0%E5%80%BC%E9%AB%98%EF%BC%8C%E5%8D%96%E5%BE%97%E8%B4%B5%22%5D%0A%20%20L%20--%3E%20C%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E9%A1%B9%E7%9B%AE%E5%BB%B6%E6%9C%9F%EF%BC%8C%E7%AB%9E%E4%BA%89%E8%80%85%E6%8A%A2%E8%B7%91%22%5D%0A%20%20R%20--%3E%20E%5B%22%E6%9C%80%E4%BC%98%EF%BC%9A%E4%B8%A4%E8%BE%B9%E6%88%90%E6%9C%AC%E7%9B%B8%E7%AD%89%E5%A4%84%22%5D%0A%20%20C%20--%3E%20E%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">Ritter 的长期统计：美国 IPO 首日平均抑价 1980–1989 年约 7%，1990–1998 年约 15%，1999–2000 年约 65%，2001 年后回落到 10% 上下——热窗口的形状直接写在抑价分布的时间剖面上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>择时证据是平均意义上的后验，对单个企业只是弱指导；窗口事前无法可靠识别。抑价与择时不可互替：发行便宜可以配合时机糟糕，两者同源（信息不对称）但发生在不同界面。监管与承销网络影响时机，估值不是唯一变量。本课不写询价与固定价格等一级市场机制设计，主干已覆盖。</p><p><span class="marginnote">常见误区：以为「等热窗口再发」稳赚。窗口事前无法可靠识别，而等下一班车的成本同样是成本——项目延期、竞争者抢跑、现金断档，任何一样都可能比估值损失更贵。择时是上千家公司平均出来的后验规律，落到一家企业头上只是弱指导。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IPO 的两个量要分开：抑价是定价问题，时机是配置问题。</li><li>择时是政策不是一次性机会主义：Baker–Wurgler 2002 的市值账面比疤痕持久存在。</li><li>热窗口是企业择时与市场筛选的合成：故事经不起兑现的企业恰在窗口内发行。</li><li>发行后弱势与理性择时兼容，是均值回归的对称面。</li><li>出处：Ritter 1991；Loughran–Ritter 2002；Baker–Wurgler 2002；Myers–Majluf 1984。</li></ul>',6))])}const g=l(p,[["render",C]]);export{D as __pageData,g as default};
